#!/usr/bin/env bash
# Supplied output checks; students do not edit this file.
set -u
program="$1"
expected_dir="$2"
actual="$(mktemp)"
trap 'rm -f "$actual"' EXIT
status=0
for input in inputs/*.txt; do
    name="$(basename "$input")"
    echo "LOCAL CHECK: $name"
    if "$program" < "$input" > "$actual"; then
        cat "$actual"
        if diff -u "$expected_dir/$name" "$actual"; then
            echo "PASS $name"
        else
            echo "FAIL $name"
            status=1
        fi
    else
        cat "$actual"
        echo "FAIL $name: program did not finish normally"
        status=1
    fi
done
exit "$status"
